<template>
  <div class="app-container warehouse-orders">
    <div class="heading"><h2>{{ bilingual('订单管理', 'Orders') }}</h2><el-button v-if="permitted('add')" type="primary" icon="Plus" :disabled="carrierBusy || saving || !!pending || !!pendingError" @click="create">{{ bilingual('新建手工订单', 'Create manual order') }}</el-button></div>
    <el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="mb16" />
    <el-alert v-if="pending || pendingError" :title="pendingError || bilingual('有一笔订单操作的结果尚未确认', 'An order operation is awaiting confirmation')" type="warning" show-icon :closable="false" class="mb16"><template v-if="pending" #default><div class="pending-id">{{ pending.payload.requestId }}</div><el-button :loading="saving" @click="retry">{{ bilingual('重试原请求', 'Retry original request') }}</el-button></template></el-alert>
    <el-form :inline="true" @submit.prevent="search">
      <el-form-item :label="bilingual('客户', 'Client')"><el-select v-model="query.client" filterable remote clearable :remote-method="q => lookup('clients', q)" class="filter"><el-option v-for="option in options.clients || []" :key="option.id" :label="option.label" :value="option.id" /></el-select></el-form-item>
      <el-form-item :label="bilingual('仓库', 'Warehouse')"><el-select v-model="query.warehouse" filterable remote clearable :remote-method="q => lookup('warehouses', q)" class="filter"><el-option v-for="option in options.warehouses || []" :key="option.id" :label="option.label" :value="option.id" /></el-select></el-form-item>
      <el-form-item :label="bilingual('状态', 'Status')"><el-select v-model="query.status" clearable class="filter"><el-option v-for="status in orderStatuses" :key="status" :label="statusLabel(status)" :value="status" /></el-select></el-form-item>
      <el-form-item :label="bilingual('关键词', 'Keyword')"><el-input v-model="query.keyword" clearable @keyup.enter="search" /></el-form-item>
      <el-form-item><el-button type="primary" icon="Search" :loading="loading" @click="search">{{ bilingual('搜索', 'Search') }}</el-button><el-button icon="Refresh" :disabled="loading" @click="resetSearch">{{ bilingual('重置', 'Reset') }}</el-button></el-form-item>
    </el-form>
    <el-table v-loading="loading" :data="rows" row-key="id" border :empty-text="bilingual('暂无订单', 'No orders')">
      <el-table-column prop="reference" :label="bilingual('订单号', 'Reference')" min-width="180" show-overflow-tooltip />
      <el-table-column :label="bilingual('客户', 'Client')" min-width="160" show-overflow-tooltip><template #default="scope">{{ relatedLabel('clients', scope.row.client) }}</template></el-table-column>
      <el-table-column :label="bilingual('仓库', 'Warehouse')" min-width="150" show-overflow-tooltip><template #default="scope">{{ relatedLabel('warehouses', scope.row.warehouse) }}</template></el-table-column>
      <el-table-column :label="bilingual('状态', 'Status')" width="140"><template #default="scope"><el-tag :type="scope.row.status === 'DESPATCHED' ? 'success' : scope.row.status === 'CANCELLED' ? 'info' : 'primary'">{{ statusLabel(scope.row.status) }}</el-tag></template></el-table-column>
      <el-table-column prop="channel" :label="bilingual('销售渠道', 'Sales channel')" min-width="145" />
      <el-table-column prop="name" :label="bilingual('收件人', 'Recipient')" min-width="150" show-overflow-tooltip />
      <el-table-column prop="postcode" :label="bilingual('邮编', 'Postcode')" width="120" />
      <el-table-column prop="tracking" :label="bilingual('运单号', 'Tracking number')" min-width="170" show-overflow-tooltip />
      <el-table-column :label="bilingual('操作', 'Actions')" width="110" fixed="right"><template #default="scope"><el-button link type="primary" :disabled="carrierBusy || saving" @click="open(scope.row.id)">{{ bilingual('查看', 'View') }}</el-button></template></el-table-column>
    </el-table>
    <pagination v-show="total > 0" :total="total" v-model:page="query.pageNum" v-model:limit="query.pageSize" @pagination="load" />
    <el-drawer v-model="opened" :title="editing ? bilingual('订单资料', 'Order details') : bilingual('订单明细', 'Order')" size="min(850px, 100%)" :close-on-click-modal="!saving && !carrierBusy" :close-on-press-escape="!saving && !carrierBusy" :show-close="!saving && !carrierBusy">
      <el-alert v-if="formError" :title="formError" type="error" show-icon :closable="false" class="mb16" />
      <el-alert v-if="detail?.workflow==='JAVA_WOO_V1'" type="info" :closable="false" class="mb16" :title="bilingual('WooCommerce 来源订单','WooCommerce source order')"><template #default><p>{{detail.sourceReference}} · {{detail.sourceOrderId}}</p><p>{{bilingual('分配、拣货和装箱会重新核对平台。快递发运和平台回传接通前不能确认发货；取消操作仅结束此仓库任务，不会在店铺退款或取消订单。','Allocation, picking and packing recheck the store. Despatch requires carrier and store feedback integration. Cancellation ends this warehouse task only; it does not cancel or refund the store order.')}}</p></template></el-alert>
      <el-alert v-if="pending" type="warning" :closable="false" :title="bilingual('上次操作结果尚未确认，新操作已暂停。', 'The last operation is unconfirmed. New operations are paused.')" class="mb16"><el-button :loading="saving" @click="retry">{{ bilingual('重试当前操作', 'Retry pending operation') }}</el-button></el-alert>
      <el-alert v-if="detail?.workflow!=='JAVA_WOO_V1'" type="info" :closable="false" :title="bilingual('手工订单可扫码装箱后申请 DPD 英国面单。已有快递申请时，不能直接拆箱、取消或人工发货。', 'Scan and pack manual orders to request DPD UK labels. An active carrier booking prevents reopening packages, cancellation and manual despatch.')" class="mb16" />
      <template v-if="editing">
        <el-form ref="formRef" :model="form" label-position="top" :disabled="carrierBusy || saving || !!pending">
          <el-row :gutter="20"><el-col v-for="item in mainFields" :key="item.key" :xs="24" :sm="12"><el-form-item :label="bilingual(item.label, item.labelEn)" :prop="item.key" :rules="rules(item.required)"><el-select v-if="item.source" v-model="form[item.key]" filterable remote :remote-method="q => lookup(item.source, q)" style="width:100%"><el-option v-for="option in withCurrent(item.source, form[item.key])" :key="option.id" :label="option.label" :value="option.id" /></el-select><el-input v-else v-model="form[item.key]" maxlength="255" /></el-form-item></el-col></el-row>
          <el-form-item :label="bilingual('销售渠道','Sales channel')"><el-select v-model="form.channelId" clearable filterable remote :disabled="!auth.hasPermi('warehouse:channels:list')" :aria-label="bilingual('销售渠道','Sales channel')" :placeholder="bilingual('Manual（未指定渠道）','Manual (no channel selected)')" :remote-method="q=>lookup('channels',q)" style="width:100%"><el-option v-for="option in withCurrent('channels',form.channelId)" :key="option.id" :label="option.label" :value="option.id" :disabled="option.active===false && option.id!==form.channelId" /></el-select><span class="channel-help">{{bilingual('用于渠道统计和收费；不选择时归为 Manual。','Used for channel reporting and pricing; leave empty for Manual.')}}</span></el-form-item>
          <h3>{{ bilingual('商品明细', 'Order lines') }}</h3>
          <div v-for="(line, index) in form.lines" :key="index" class="line-editor"><el-form-item :prop="'lines.' + index + '.product'" :rules="rules(true)" :label="bilingual('商品', 'Product')"><el-select v-model="line.product" filterable remote :remote-method="q => lookup('products', q)" style="width:100%"><el-option v-for="option in withCurrent('products', line.product)" :key="option.id" :label="option.label" :value="option.id" /></el-select></el-form-item><el-form-item :label="bilingual('数量', 'Quantity')" :prop="'lines.' + index + '.quantity'" :rules="rules(true)"><el-input-number v-model="line.quantity" :min="1" :precision="0" controls-position="right" /></el-form-item><el-button icon="Delete" :aria-label="bilingual('移除此行', 'Remove line')" :disabled="form.lines.length === 1" @click="form.lines.splice(index, 1)" /></div>
          <el-button icon="Plus" plain :disabled="form.lines.length >= 200" @click="form.lines.push({product:'',quantity:1})">{{ bilingual('添加商品', 'Add product') }}</el-button>
          <h3>{{ bilingual('收货地址', 'Delivery address') }}</h3><el-row :gutter="20"><el-col v-for="item in addressFields" :key="item.key" :xs="24" :sm="12"><el-form-item :label="bilingual(item.label, item.labelEn)" :prop="item.key" :rules="rules(item.required)"><el-input v-model="form[item.key]" :type="item.key === 'email' ? 'email' : 'text'" maxlength="255" /></el-form-item></el-col></el-row>
          <el-form-item :label="bilingual('订单货值', 'Order value')"><el-input v-model="form.orderValue" inputmode="decimal" maxlength="35" /></el-form-item>
          <el-form-item :label="bilingual('备注', 'Notes')"><el-input v-model="form.notes" type="textarea" :rows="3" maxlength="2000" /></el-form-item>
        </el-form>
      </template>
      <template v-else-if="detail">
        <el-descriptions :column="detailColumns" border class="order-summary"><el-descriptions-item :label="bilingual('销售渠道','Sales channel')">{{detail.channel || 'Manual'}}</el-descriptions-item><el-descriptions-item :label="bilingual('订单号', 'Reference')">{{ detail.reference }}</el-descriptions-item><el-descriptions-item :label="bilingual('状态', 'Status')">{{ statusLabel(detail.status) }}</el-descriptions-item><el-descriptions-item :label="bilingual('客户', 'Client')">{{ relatedLabel('clients', detail.client) }}</el-descriptions-item><el-descriptions-item :label="bilingual('仓库', 'Warehouse')">{{ relatedLabel('warehouses', detail.warehouse) }}</el-descriptions-item><el-descriptions-item :label="bilingual('收件人', 'Recipient')">{{ detail.name }}</el-descriptions-item><el-descriptions-item :label="bilingual('运单号', 'Tracking number')">{{ detail.tracking || '—' }}</el-descriptions-item><el-descriptions-item v-if="detail.billingStatus" :label="bilingual('计费状态', 'Billing status')">{{ detail.billingStatus === 'TIER_PENDING' ? bilingual('待周期结算', 'Awaiting period billing') : detail.billingStatus === 'CHARGED' ? bilingual('费用已记录', 'Charges recorded') : detail.billingStatus }}</el-descriptions-item><el-descriptions-item :span="detailColumns" :label="bilingual('收货地址', 'Address')">{{ [detail.address1,detail.address2,detail.address3,detail.town,detail.county,detail.postcode,detail.country].filter(Boolean).join(', ') }}</el-descriptions-item></el-descriptions>
        <h3>{{ bilingual('商品明细', 'Order lines') }}</h3><el-table :data="detail.lines || []" border><el-table-column :label="bilingual('商品', 'Product')"><template #default="scope">{{ relatedLabel('products', scope.row.product) }}</template></el-table-column><el-table-column prop="quantity" :label="bilingual('数量', 'Quantity')" width="120" /></el-table>
        <h3>{{ bilingual('库存分配记录', 'Allocation history') }}</h3><el-table :data="detail.allocations || []" border :empty-text="bilingual('尚未分配库存', 'No stock allocated')"><el-table-column v-for="item in allocationColumns" :key="item.key" :prop="item.key" :label="bilingual(item.label,item.labelEn)" min-width="130" show-overflow-tooltip><template #default="scope">{{ allocationCell(scope.row,item.key) }}</template></el-table-column></el-table>
        <OrderWorkPanel :order="detail" :busy="saving || carrierBusy" :blocked="!!pending || !!pendingError || !!detail.carrierShipment?.id" @work="submitWork" @refresh="open(detail.id)" />
        <CarrierOrderPanel :order="detail" :blocked="saving || !!pending || !!pendingError" @busy="carrierBusy=$event" @changed="open(detail.id); load()" />
      </template>
      <template #footer><el-button :disabled="carrierBusy || saving" @click="opened = false">{{ bilingual('关闭', 'Close') }}</el-button><template v-if="editing"><el-button type="primary" :loading="saving" :disabled="!!pending || !!pendingError" @click="save">{{ bilingual('保存', 'Save') }}</el-button></template><template v-else-if="detail"><el-button v-if="permitted('edit') && orderEditable(detail)" :disabled="carrierBusy || saving || !!pending || !!pendingError" @click="editDetail">{{ bilingual('编辑', 'Edit') }}</el-button><el-button v-for="action in actions" :key="action" :type="action === 'cancel' ? 'danger' : 'primary'" :plain="action === 'cancel'" :disabled="carrierBusy || saving || !!pending || !!pendingError || workBlocksAction(detail, action)" @click="perform(action)">{{ actionLabel(action) }}</el-button></template></template>
    </el-drawer>
  </div>
</template>
<script setup>
import { computed, reactive, ref, onMounted, toRaw, watch } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { useWindowSize } from '@vueuse/core'
import { useRoute } from 'vue-router'
import auth from '@/plugins/auth'
import OrderWorkPanel from './OrderWorkPanel.vue'
import CarrierOrderPanel from './CarrierOrderPanel.vue'
const carrierBusy=ref(false)
import { workPayload, workBlocksAction } from '@/warehouse/order-work'
import useUserStore from '@/store/modules/user'
import { bilingual } from '@/warehouse/i18n'
import { rejectedBeforeCommit } from '@/warehouse/inventory'
import { intakeMessages } from '@/warehouse/integration-acceptance'
import { orderStatuses, orderActions, orderEditable, orderPayload, blankOrder, orderPendingKey, readPendingOrder } from '@/warehouse/orders'
import { listWarehouseOrders, getWarehouseOrder, createWarehouseOrder, updateWarehouseOrder, actionWarehouseOrder, workWarehouseOrder, getWarehouseLookups } from '@/api/warehouse'
const route=useRoute()
const operationError=e=>intakeMessages[e?.response?.data?.error]?bilingual(...intakeMessages[e.response.data.error]):e.message||bilingual('请求失败','Request failed')
const user = useUserStore(), permitted = action => auth.hasPermi('warehouse:orders:' + action)
const query = reactive({ pageNum:1, pageSize:20, client:'',warehouse:'',status:'',keyword:'' }), rows = ref([]), total = ref(0), loading = ref(false), saving = ref(false), error = ref(''), formError = ref(''), opened = ref(false), editing = ref(false), detail = ref(null), form = ref(blankOrder()), formRef = ref(), pending = ref(null), pendingError = ref(''), options = reactive({})
const { width } = useWindowSize()
const detailColumns = computed(() => width.value < 600 ? 1 : 2)
const actions = computed(() => orderActions(detail.value).filter(permitted))
const statusLabel = value => bilingual(({NEW:'新建',HOLDING:'暂停',ALLOCATED:'已分配',PICKED:'已拣货',DESPATCHED:'已发货',CANCELLED:'已取消'})[value] || value, ({NEW:'New',HOLDING:'On hold',ALLOCATED:'Allocated',PICKED:'Picked',DESPATCHED:'Despatched',CANCELLED:'Cancelled'})[value] || value)
const actionLabel = value => bilingual(({allocate:'分配库存',pick:'确认拣货',cancel:'取消订单',despatch:'确认发货',hold:'暂停订单',release:'解除暂停'})[value], ({allocate:'Allocate stock',pick:'Confirm picking',cancel:'Cancel order',despatch:'Confirm despatch',hold:'Hold order',release:'Release hold'})[value])
const mainFields = [{key:'client',source:'clients',label:'客户',labelEn:'Client',required:true},{key:'warehouse',source:'warehouses',label:'仓库',labelEn:'Warehouse',required:true},{key:'reference',label:'订单号',labelEn:'Reference',required:true}]
const addressFields = [{key:'name',label:'收件人',labelEn:'Recipient',required:true},{key:'companyName',label:'公司名称',labelEn:'Company name'},{key:'address1',label:'地址第一行',labelEn:'Address line 1',required:true},{key:'address2',label:'地址第二行',labelEn:'Address line 2'},{key:'address3',label:'地址第三行',labelEn:'Address line 3'},{key:'town',label:'城市',labelEn:'Town / city',required:true},{key:'county',label:'地区',labelEn:'County / region'},{key:'postcode',label:'邮编',labelEn:'Postcode',required:true},{key:'country',label:'国家代码',labelEn:'Country code',required:true},{key:'email',label:'电子邮箱',labelEn:'Email'},{key:'phone',label:'电话',labelEn:'Phone'}]
const allocationColumns = [{key:'state',label:'分配状态',labelEn:'Allocation state'},{key:'product',label:'商品',labelEn:'Product'},{key:'warehouse',label:'仓库',labelEn:'Warehouse'},{key:'location',label:'库位',labelEn:'Location'},{key:'quantity',label:'数量',labelEn:'Quantity'},{key:'batch',label:'批次',labelEn:'Batch'},{key:'serial',label:'序列号',labelEn:'Serial'},{key:'expiry',label:'到期日',labelEn:'Expiry'},{key:'expiryWarning',label:'有效期警示',labelEn:'Expiry warning'},{key:'receivedAt',label:'原始入库时间',labelEn:'Original receipt'}]
const allocationCell = (row,key) => key==='state'?bilingual(({RESERVED:'已预留',RELEASED:'已释放',CONSUMED:'已出库'})[row.state]||row.state,({RESERVED:'Reserved',RELEASED:'Released',CONSUMED:'Consumed'})[row.state]||row.state):key==='product'?(row.sku||row.productName||relatedLabel('products',row.product)):key==='warehouse'?(row.warehouseName||relatedLabel('warehouses',row.warehouse)):key==='location'?(row.locationName||row.location||'—'):row[key]??'—'
const rules = required => required ? [{required:true,message:bilingual('请填写或选择此项','Complete this field'),trigger:['blur','change']}] : []
const relatedLabel = (source,id) => options[source]?.find(item => item.id === id)?.label || id || '—'
const withCurrent = (source,id) => id && !options[source]?.some(item => item.id === id) ? [{id,label:source==='channels'?(detail.value?.channel||String(id)):String(id)},...(options[source] || [])] : options[source] || []
const tickets = new Map()
async function lookup(source,q='',scope){if(source==='channels'&&!auth.hasPermi('warehouse:channels:list'))return;const ticket=(tickets.get(source)||0)+1;tickets.set(source,ticket);try{const result=await getWarehouseLookups(source,q,scope||(source==='products'&&form.value.client?{client:form.value.client}:{}));if(tickets.get(source)===ticket)options[source]=result.data}catch(e){error.value=e.message||bilingual('关联资料加载失败','Could not load related records')} }
let generation=0,detailGeneration=0
async function load(){const ticket=++generation;loading.value=true;error.value='';try{const result=await listWarehouseOrders({...query});if(ticket===generation){rows.value=result.rows;total.value=result.total}}catch(e){if(ticket===generation)error.value=e.message||bilingual('订单读取失败','Could not load orders')}finally{if(ticket===generation)loading.value=false}}
function search(){query.pageNum=1;load()}
function resetSearch(){Object.assign(query,{pageNum:1,client:'',warehouse:'',status:'',keyword:''});load()}
let assigningForm=false
function create(){if(!permitted('add')||pending.value||pendingError.value||saving.value)return;detailGeneration++;detail.value=null;assigningForm=true;form.value={...blankOrder(),client:query.client,warehouse:query.warehouse};assigningForm=false;formError.value='';editing.value=true;opened.value=true;lookup('products');lookup('channels')}
async function open(id){const ticket=++detailGeneration;try{const result=await getWarehouseOrder(id);if(ticket!==detailGeneration)return;detail.value=result.data;editing.value=false;formError.value='';opened.value=true;lookup('products','',detail.value.client?{client:detail.value.client}:{})}catch(e){error.value=e.message||bilingual('详情读取失败','Could not load order details')}}
function editDetail(){if(!permitted('edit')||!orderEditable(detail.value))return;assigningForm=true;form.value={...blankOrder(),...structuredClone(toRaw(detail.value))};assigningForm=false;editing.value=true;formError.value='';lookup('products');lookup('channels')}
watch(()=>form.value.client,()=>{if(assigningForm||!editing.value||pending.value)return;form.value.lines=form.value.lines.map(line=>({...line,product:''}));lookup('products')},{flush:'sync'})
function keepPending(next){sessionStorage.setItem(orderPendingKey(user.id),JSON.stringify(next));pending.value=next}
async function sendPending(retrying){try{const current=toRaw(pending.value),payload=structuredClone(toRaw(current.payload)),result=current.type==='create'?await createWarehouseOrder(payload):current.type==='update'?await updateWarehouseOrder(current.id,payload):current.type==='work'?await workWarehouseOrder(current.id,payload):await actionWarehouseOrder(current.id,payload);sessionStorage.removeItem(orderPendingKey(user.id));pending.value=null;formError.value='';error.value='';detail.value=result.data;editing.value=false;opened.value=true;if(current.type!=='work'||current.payload.action!=='scan')ElMessage.success({message:bilingual('操作已完成','Operation completed'),grouping:true,duration:1500});await load()}catch(e){if(!retrying&&rejectedBeforeCommit(e)){sessionStorage.removeItem(orderPendingKey(user.id));pending.value=null;formError.value=operationError(e)}else{formError.value=operationError(e)+' · '+bilingual('结果尚未确认，请重试原请求。','The result is unconfirmed. Retry the original request.');error.value=formError.value}}}
async function retry(){if(saving.value||!pending.value||pendingError.value)return;const current=pending.value;if(!permitted(current.type==='create'?'add':current.type==='update'?'edit':current.payload.action))return;saving.value=true;try{await sendPending(true)}finally{saving.value=false}}
async function save(){if(saving.value||pending.value||pendingError.value||!permitted(detail.value?'edit':'add'))return;saving.value=true;formError.value='';try{if(!await formRef.value.validate().catch(()=>false))return;const version=detail.value?._version;if(detail.value&&!Number.isInteger(version))throw Error(bilingual('缺少记录版本，请重新打开订单','Record version is missing. Reopen the order.'));keepPending({type:detail.value?'update':'create',...(detail.value?{id:detail.value.id}:{}),payload:orderPayload(form.value,{requestId:crypto.randomUUID(),version}),createdAt:new Date().toISOString()});await sendPending(false)}catch(e){formError.value=({invalid_lines:bilingual('每单需有1至200行商品，数量须为正整数且合计不超过10000000。','Use 1–200 product lines with positive whole quantities totalling at most 10,000,000.'),duplicate_product:bilingual('同一商品请合并成一行。','Combine duplicate products into one line.'),invalid_order_value:bilingual('订单货值不能小于零。','Order value must not be negative.')})[e.message]||e.message||bilingual('保存失败，输入已保留','Save failed. Your input has been kept.')}finally{saving.value=false}}
async function submitWork(input){
  if(saving.value||pending.value||pendingError.value||!detail.value||!permitted(input.action))return
  saving.value=true;formError.value=''
  try{
    const payload=workPayload(input,{requestId:crypto.randomUUID(),version:detail.value._version})
    keepPending({type:'work',id:detail.value.id,payload,createdAt:new Date().toISOString()})
    await sendPending(false)
  }catch(e){formError.value=({work_version:bilingual('记录版本缺失，请刷新作业记录。','Record version is missing. Refresh work.'),work_fields:bilingual('请填写完整的条码、包裹编号或更正原因。','Complete the barcode, package code or correction reason.'),work_measurements:bilingual('重量须为正数，最多三位小数且不超过100000 kg；尺寸最多两位小数且不超过1000 cm。','Weight must be positive, at most 100,000 kg with 3 decimal places; dimensions at most 1,000 cm with 2 decimal places.'),work_lines:bilingual('每箱须有1至200行，数量为正整数，不能重复分配行。','Use 1–200 distinct allocations per box with positive whole quantities.')})[e.message]||e.message}finally{saving.value=false}
}
async function perform(action){if(saving.value||pending.value||pendingError.value||!permitted(action)||!orderActions(detail.value).includes(action)||workBlocksAction(detail.value,action))return;saving.value=true;formError.value='';const id=detail.value.id;try{let tracking='';try{if(action==='despatch'){const result=await ElMessageBox.prompt(bilingual('填写运单号（可留空）。此操作会扣减已分配库存，不能撤回。','Enter a tracking number (optional). This operation deducts allocated stock and cannot be undone.'),actionLabel(action),{confirmButtonText:bilingual('确认发货','Confirm despatch'),cancelButtonText:bilingual('取消','Cancel'),inputValue:detail.value.tracking||''});tracking=result.value||''}else await ElMessageBox.confirm(bilingual('确认执行：','Confirm: ')+actionLabel(action)+'?',detail.value.reference,{type:'warning',confirmButtonText:bilingual('确认','Confirm'),cancelButtonText:bilingual('取消','Cancel')})}catch{return}keepPending({type:'action',id,payload:{requestId:crypto.randomUUID(),action,...(action==='despatch'?{tracking}:{})},createdAt:new Date().toISOString()});await sendPending(false)}catch(e){formError.value=e.message||bilingual('请求未发送，请检查浏览器存储权限','The request was not sent. Check browser storage permissions.')}finally{saving.value=false}}
onMounted(async()=>{try{pending.value=readPendingOrder(sessionStorage,user.id)}catch{pendingError.value=bilingual('上次订单请求记录无法读取，请先联系管理员核对。','The previous order request cannot be read. Ask an administrator to check it first.')}await Promise.all([load(),...['clients','warehouses','products'].map(source=>lookup(source))]);if(typeof route.query.order==='string'&&permitted('query'))await open(route.query.order)})
watch(()=>route.query.order,id=>{if(typeof id==='string'&&permitted('query')&&!saving.value)open(id)})
</script>
